-- Extension de la base PUREVITANUTRITION. Ne supprime rien.
create table if not exists public.categories(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),nom text not null,parent_id bigint references public.categories(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.clients(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),nom text not null,telephone text,email text,adresse text,solde_credit numeric(12,2) not null default 0,limite_credit numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.paiements_clients(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),client_id bigint not null references public.clients(id) on delete cascade,montant numeric(12,2) not null check(montant>0),mode_paiement text not null default 'especes',created_at timestamptz not null default now());
create table if not exists public.depenses(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),libelle text not null,montant numeric(12,2) not null check(montant>=0),categorie text,mode_paiement text default 'especes',created_at timestamptz not null default now());
create table if not exists public.magasins(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),nom text not null,adresse text,telephone text,created_at timestamptz not null default now());
create table if not exists public.roles_utilisateurs(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('admin','caissier','stock','comptable')),created_at timestamptz not null default now(),unique(user_id));
create table if not exists public.journal_activite(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,action text not null,table_nom text,ligne_id bigint,details jsonb,created_at timestamptz not null default now());
-- RLS : chaque utilisateur ne voit que ses propres données.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['categories','clients','paiements_clients','depenses','magasins','roles_utilisateurs','journal_activite'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy if not exists categories_own on public.categories for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists clients_own on public.clients for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists paiements_clients_own on public.paiements_clients for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists depenses_own on public.depenses for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists magasins_own on public.magasins for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists roles_select_own on public.roles_utilisateurs for select to authenticated using(auth.uid()=user_id);
create policy if not exists journal_select_own on public.journal_activite for select to authenticated using(auth.uid()=user_id);
grant select,insert,update,delete on public.categories,public.clients,public.paiements_clients,public.depenses,public.magasins to authenticated; grant select on public.roles_utilisateurs,public.journal_activite to authenticated; grant usage,select on all sequences in schema public to authenticated;
